var e=Object.assign({"./locales/en/docs/alert.json":{title:`Alert`,description:`Displays an important message inline, such as system notices or the result of an action.`,demos:{variants:{title:`Variants`,description:`Info (default), success, warning and error.`},"with-title":{title:`With title`,description:`Add a title above the content. showIcon={false} hides the icon.`},types:{title:`Styles`,description:`Default, outlined and filled styles.`},sizes:{title:`Sizes`,description:`Small, medium (default) and large.`},closable:{title:`Closable`,description:`closable adds a close button; closeIcon replaces its icon and onClose is called on close.`},"with-action":{title:`With action`,description:`Render buttons or links on the right with action.`},collapsible:{title:`Collapsible`,description:`With a title, collapsible lets users expand and collapse the content.`},banner:{title:`Banner`,description:`Banner mode for notices at the top of a page.`},appearance:{title:`Appearance`,description:`Custom icon, elevation, outlined, filled and corner radius options.`},animations:{title:`Animations`,description:`Choose the entrance animation or turn it off.`}},api:{AlertProps:{title:`Alert title`,children:`Alert content`,variant:`Semantic variant, which sets the color and default icon`,size:`Alert size`,type:`Visual style`,showIcon:`Shows the variant icon`,icon:`Custom icon, replacing the variant icon`,closable:`Shows a close button`,closeIcon:`Custom close icon`,onClose:`Called when the close button is clicked`,animation:`Plays an entrance animation`,animationName:`Entrance animation name`,className:`Additional class name`,style:`Inline styles`,action:`Action area rendered on the right, e.g. buttons`,outlined:`Shows a border`,filled:`Fills the background with the variant color`,banner:`Banner mode, suited to page-level notices at the top of a page`,elevation:`Adds a drop shadow`,rounded:`Rounds the corners`,borderRadius:`Custom corner radius`,collapsible:`Lets the content be expanded and collapsed (requires a title)`,defaultExpanded:`Whether the content is initially expanded`,onExpand:`Called when the content is expanded or collapsed`}}},"./locales/en/docs/auto-complete.json":{title:`AutoComplete`,description:`A text input that suggests matching options while the user types.`,demos:{basic:{title:`Basic usage`,description:`Options whose label contains the typed text are suggested; textFieldProps are forwarded to the input.`},controlled:{title:`Controlled`,description:`value / onChange control the input text, onSelect reports the chosen option and onDropdownVisibleChange the dropdown state.`},"rich-options":{title:`Icons, descriptions and states`,description:`In basic mode an option can have an icon and a description, and can be highlighted or disabled.`},"custom-render":{title:`Custom rendering`,description:`Set mode="custom" and renderOption to fully control how options look; renderEmpty replaces the empty state.`},grouped:{title:`Grouped options`,description:`groupBy returns a group name for each option; groups are shown under headings in order of appearance.`},multiple:{title:`Multiple selection`,description:`With multiple, selected options become removable tags; maxTagCount collapses the rest into "+N".`},"filter-sort":{title:`Custom filter and sort`,description:`filterOption replaces the default "contains" matching and sortOption orders the results.`},"async-loading":{title:`Remote search`,description:`Fetch options as the user types and show loading while the request is pending.`},appearance:{title:`Dropdown placement and colors`,description:`Customize placement, offset, animation and the dropdown, hover and highlight background colors.`}},keyboard:{title:`Keyboard and accessibility`,arrows:`Arrow Down / Arrow Up move through the visible options (wrapping around).`,enter:`Enter selects the active option; disabled options are skipped on selection.`,escape:`Escape closes the dropdown.`,aria:`The input exposes the combobox role with aria-expanded, aria-controls and aria-activedescendant pointing to the listbox options.`},api:{AutoCompleteProps:{name:`Name of the input`,label:`Label of the input`,mode:`"basic" renders icon / label / description; "custom" uses renderOption`,value:`Input value (controlled)`,onChange:`Called when the input text changes (typing or selecting an option)`,options:`Options to suggest`,defaultValue:`Initial input value (uncontrolled)`,onSelect:`Called when an option is selected (mouse or keyboard)`,groupBy:`Returns the group name of an option; options are grouped under headings`,multiple:`Allows selecting several options, shown as removable tags`,maxTagCount:`Maximum number of tags shown in multiple mode; the rest are summarized as "+N"`,renderOption:`Custom option renderer (used when mode is "custom")`,renderEmpty:`Custom content shown when no option matches`,loading:`Shows a loading indicator in the dropdown`,textFieldProps:`Props forwarded to the underlying TextField`,emptyProps:`Props forwarded to the default Empty state`,popperProps:`Props forwarded to the dropdown Popper`,placement:`Dropdown placement`,offset:`Dropdown offset`,dropdownBgColor:`Background color of the dropdown`,highlightBgColor:`Background color of highlighted options`,hoverBgColor:`Background color of hovered / keyboard-focused options`,animation:`Animates the dropdown when it opens`,filterOption:`Custom filter; by default options whose label contains the input (case-insensitive) are shown`,sortOption:`Compare function used to sort the filtered options`,onOptionClick:`Called when an option is clicked with the mouse`,onDropdownVisibleChange:`Called when the dropdown opens or closes`},AutoCompleteOption:{label:`Text displayed for the option and written to the input when selected`,value:`Unique value of the option`,disabled:`Prevents the option from being selected`,highlight:`Highlights the option (e.g. as a recommendation)`,icon:`Icon displayed before the label (basic mode)`,description:`Secondary text displayed under the label (basic mode)`,group:`Free-form group identifier, typically read by groupBy`,style:`Inline styles of the option`}}},"./locales/en/docs/avatar.json":{title:`Avatar`,description:`Represents a person with a picture or, when no image is available, the initial of their name.`,demos:{basic:{title:`Basic usage`,description:`Pass src for a picture; otherwise the first letter of name is shown. name is also used as the image alt text.`},shapes:{title:`Shapes`,description:`circle (default), rounded or square.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},group:{title:`Avatar group`,description:`Wrap avatars in AvatarGroup and use stacked for overlapping; count shows how many more people there are.`}},api:{AvatarProps:{src:`Image URL. When omitted, the first letter of name is shown`,name:`Name of the person; used for the initial, alt text and accessible label`,shape:`Avatar shape`,size:`Avatar size`,className:`Additional class name`,stacked:`Uses tighter margins for overlapping avatars`},AvatarGroupProps:{count:`Number of additional avatars, shown as a "+N" indicator`,className:`Additional class name`,children:`Avatar elements`}}},"./locales/en/docs/badge.json":{title:`Badge`,description:`A small count or status indicator attached to the corner of another element.`,demos:{basic:{title:`Basic usage`,description:`Wrap an element and set content. Give the badge an ariaLabel that describes what the number means.`},variants:{title:`Variants`,description:`Nine color schemes; error is an alias of danger.`},positions:{title:`Positions`,description:`Attach the badge to any corner with position.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},dot:{title:`Dot`,description:`dot replaces the content with a small dot, for "something new" indicators.`},"with-icon":{title:`With icon`,description:`icon is displayed before the content.`},"custom-style":{title:`Custom styles`,description:`Override colors, border and radius with bgColor, textColor, borderWidth, borderColor and borderRadius.`}},api:{BadgeProps:{children:`Element the badge is attached to`,className:`Additional class name of the badge`,variant:`Color scheme of the badge`,size:`Badge size`,content:`Content displayed inside the badge (count, short text...)`,position:`Corner of the children the badge is placed on`,dot:`Renders a small dot instead of content`,bgColor:`Custom background color`,textColor:`Custom text color`,borderRadius:`Custom border radius (CSS value)`,borderWidth:`Custom border width (CSS value)`,borderColor:`Custom border color`,ariaLabel:`Accessible label of the badge, e.g. "5 unread messages"`,icon:`Icon displayed before the content`}}},"./locales/en/docs/button.json":{title:`Button`,description:`Triggers an action or event, such as submitting a form or opening a dialog.`,demos:{basic:{title:`Basic usage`,description:`A button with a click handler. All native <button> attributes are forwarded.`},variants:{title:`Variants`,description:`Use variant to communicate the intent of the action.`},sizes:{title:`Sizes`,description:`Four sizes: small, medium (default), large and xlarge.`},shapes:{title:`Shapes and radius`,description:`Preset shapes, or a custom borderRadius preset / pixel value.`},states:{title:`States`,description:`Loading, disabled and active states. Loading blocks clicks while an action is running.`},"with-icon":{title:`With icons`,description:`Combine text and icons. Give icon-only buttons an ariaLabel.`}},api:{ButtonProps:{onClick:`Called when the button is clicked (not called while disabled)`,children:`Button content`,className:`Additional class name`,variant:`Visual style of the button`,size:`Button size`,ariaLabel:`Accessible label, required when the button only contains an icon`,disabled:`Disables the button`,loading:`Shows a spinner and blocks interaction`,active:`Renders the button in its pressed/active state`,shape:`Preset shape of the button`,borderRadius:`Corner radius: a preset or a number of pixels`,style:`Inline styles`}}},"./locales/en/docs/card.json":{title:`Card`,description:`A container that groups related content and actions, composed of CardHeader, CardTitle, CardDescription, CardContent and CardFooter.`,demos:{basic:{title:`Basic usage`,description:`Compose a card from its header (title and description), content and footer.`},variants:{title:`Variants`,description:`Five visual styles: default, outlined, shadow, elevated and filled.`},types:{title:`Header and footer`,description:`type hides the CardHeader and/or CardFooter without changing the markup.`},"custom-colors":{title:`Custom colors`,description:`CardHeader, CardContent and CardFooter accept bgColor and textColor.`},animation:{title:`Content animation`,description:`CardContent can play a fadeIn, slideIn or zoomIn entrance animation.`}},api:{CardProps:{children:`Card content, usually CardHeader, CardContent and CardFooter`,variant:`Visual style of the card`,type:`Hides the CardHeader and/or CardFooter (noHeader, noFooter, noHeaderFooter)`,className:`Additional class name`},CardHeaderProps:{children:`Header content, usually CardTitle and CardDescription`,className:`Additional class name`,bgColor:`Header background color`,textColor:`Header text color`},CardTitleProps:{children:`Title text, rendered as an <h3>`,className:`Additional class name`},CardDescriptionProps:{children:`Secondary text shown below the title`,className:`Additional class name`},CardContentProps:{children:`Main content of the card`,className:`Additional class name`,bgColor:`Content background color`,textColor:`Content text color`,animation:`Entrance animation of the content`},CardFooterProps:{children:`Footer content, e.g. actions`,className:`Additional class name`,bgColor:`Footer background color`,textColor:`Footer text color`}}},"./locales/en/docs/cascader.json":{title:`Cascader`,description:`Selects a value from a hierarchy of options, one level at a time (e.g. country / region / city).`,demos:{basic:{title:`Basic usage`,description:`Click an option to open the next level; choosing a leaf completes the selection.`},"default-value":{title:`Default value`,description:`defaultValue takes the path of values, one per level.`},controlled:{title:`Controlled`,description:`Pass value and update it in onChange. Clearing calls onChange with an empty array.`},hover:{title:`Expand on hover`,description:`With expandTrigger="hover", sub-menus open when the pointer hovers a parent option.`},search:{title:`Search`,description:`showSearch lets users type to filter every path; filter customizes the matching.`},"display-render":{title:`Custom display`,description:`displayRender formats the text shown in the input; here only the last level is displayed and allowClear is off.`},disabled:{title:`Disabled`,description:`Disable individual options with option.disabled, or the whole component with disabled.`},"lazy-load":{title:`Load options lazily`,description:`loadData is called for options without children that are not isLeaf. Set loading on the option and add its children to options when they arrive.`},"custom-option":{title:`Custom options and levels`,description:`optionRender renders each option with its level, maxLevel limits the depth, and dropdownStyle / optionStyle adjust the menu.`}},api:{CascaderProps:{label:`Label of the input`,name:`Name of the input`,options:`Option tree`,value:`Selected path of values (controlled)`,defaultValue:`Initially selected path of values (uncontrolled)`,onChange:`Called when a leaf option is selected or the value is cleared`,displayRender:`Formats the text shown in the input; by default labels are joined with " / "`,disabled:`Disables the cascader`,placeholder:`Placeholder of the input`,allowClear:`Shows a clear button when a value is selected`,expandTrigger:`How sub-menus are expanded`,className:`Additional class name`,showSearch:`Allows typing to search all paths`,filter:`Custom search predicate; by default paths whose labels contain the input match`,loadData:`Loads children lazily for options without children that are not isLeaf; update options yourself`,dropdownClassName:`Additional class name of the dropdown`,optionRender:`Custom option renderer`,width:`Width of the component`,maxLevel:`Maximum number of levels shown`,dropdownStyle:`Inline styles of the dropdown`,optionStyle:`Inline styles of every option`},CascaderOption:{value:`Value of the option, unique among its siblings`,label:`Text displayed for the option`,children:`Options of the next level`,disabled:`Prevents the option from being selected`,isLeaf:`Marks the option as a leaf (no children to load) when using loadData`,loading:`Shows a loading indicator while its children are being loaded`}}},"./locales/en/docs/checkbox.json":{title:`Checkbox`,description:`Lets users select one or more options, with indeterminate, error and custom styling support.`,demos:{basic:{title:`Basic usage`,description:`An uncontrolled checkbox with a label; use defaultChecked for the initial state.`},controlled:{title:`Controlled`,description:`Pass checked and onChange. onChange receives the new checked state and the change event.`},indeterminate:{title:`Indeterminate`,description:`A "select all" checkbox that is indeterminate while only some items are selected.`},"sizes-and-shapes":{title:`Sizes and shapes`,description:`Three sizes and three box shapes: square (default), rounded and circle.`},"label-placement":{title:`Label placement`,description:`Place the label at the start, end (default), top or bottom of the box.`},states:{title:`States`,description:`Disabled checkboxes, and required for use in native forms.`},"custom-style":{title:`Custom style`,description:`Customize the box, border and checkmark colors, or show a custom icon when checked (controlled mode).`},error:{title:`Error state`,description:`error with helperText highlights a checkbox that needs attention.`}},api:{CheckboxProps:{checked:`Checked state (controlled)`,defaultChecked:`Initial checked state (uncontrolled)`,disabled:`Disables the checkbox`,indeterminate:`Shows the indeterminate (partially checked) state`,name:`Name of the input, used in forms`,onChange:`Called with the new checked state and the change event`,shape:`Box shape`,size:`Checkbox size`,label:`Label text`,className:`Additional class name`,checkmarkColor:`Custom checkmark color`,boxColor:`Custom box background color`,boxBorderColor:`Custom box border color`,icon:`Custom icon shown when checked (controlled mode only)`,required:`Marks the input as required`,error:`Shows the error state`,errorIcon:`Icon shown before the helper text in the error state`,helperText:`Helper or error text shown below the checkbox`,labelPlacement:`Position of the label relative to the box`,ref:`Ref to the underlying <input> element`}}},"./locales/en/docs/chip.json":{title:`Chip`,description:`Compact elements that represent an input, attribute or filter, optionally clickable or deletable.`,demos:{basic:{title:`Basic usage`,description:`A chip only needs a label.`},variants:{title:`Variants`,description:`filled (default), outlined and soft.`},colors:{title:`Colors`,description:`Seven color schemes from the theme.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},"icon-avatar":{title:`Icon and avatar`,description:`Show an icon or an avatar before the label.`},deletable:{title:`Deletable`,description:`Providing onDelete renders a delete button; customize it with deleteIcon and its accessible name with deleteLabel.`},clickable:{title:`Clickable and selected`,description:`clickable turns the chip into a focusable button activated with Enter or Space; selected highlights the active filter.`},states:{title:`Loading and disabled`,description:`loading shows a spinner; disabled hides the delete button and blocks clicks.`}},api:{ChipProps:{label:`Text of the chip`,variant:`Visual style`,color:`Color scheme`,size:`Chip size`,icon:`Icon displayed before the label`,avatar:`Avatar displayed before the label`,onDelete:`Called when the delete button is clicked; providing it shows the delete button`,onClick:`Called when the chip is clicked (requires clickable)`,disabled:`Disables the chip and hides the delete button`,className:`Additional class name`,deleteIcon:`Custom delete icon`,deleteLabel:`Accessible label for the delete button`,clickable:`Makes the chip a keyboard-operable button`,loading:`Shows a spinner before the label`,selected:`Shows the selected state`}}},"./locales/en/docs/config-provider.json":{title:`ConfigProvider`,description:`Provides the theme and the language of lib-core to your application, and exposes them through useConfig().`,usage:{title:`Usage`,text:`Render one ConfigProvider at the root of your application. It applies the theme as CSS variables on <html>, sets the language of lib-core's built-in texts, and provides both to useConfig().`,dynamic:`Both props are reactive: store them in state to let users switch theme or language at runtime.`,global:`Theme and language are global: the provider writes CSS variables on <html> and changes lib-core's i18next language. A nested ConfigProvider therefore re-themes the whole page, not only its children. To theme a single region, set the CSS variables on a wrapper element instead (see the custom theme example).`},demos:{"use-config":{title:`Reading the configuration`,description:`useConfig() returns the configured theme, the resolved theme and the locale of the nearest provider. Change the site theme in the header to see it update.`},"custom-theme":{title:`Custom theme`,description:`A custom theme built from themes.light. Passed to ConfigProvider it would re-theme the page; here its tokens are applied as CSS variables on one container.`},locale:{title:`Locale`,description:`The locale prop sets the language of lib-core's built-in texts (en, zh or fr). The demo restores English when it unmounts, because the language is global.`}},api:{ConfigContextProviderProps:{theme:`Theme to apply: "auto" (follows prefers-color-scheme), a built-in theme name, a theme object, or a { light, dark } pair. Applied as CSS variables on the document root.`,locale:`Language of lib-core's built-in texts (changes it globally).`,children:`Application content.`},ConfigContextProps:{theme:`Theme as configured (may be "auto" or a { light, dark } pair).`,resolvedTheme:`Theme currently applied after resolving "auto" and { light, dark } pairs: a built-in theme name or a theme object.`,locale:`Current locale of lib-core's built-in texts.`},Locale:{language:`Language of lib-core's built-in texts: "en", "zh" or "fr".`}},context:{title:`ConfigContext`,text:`useConfig() throws when there is no ConfigProvider above it, which catches setup mistakes early. Read ConfigContext directly when the provider is optional: it returns undefined instead of throwing.`}},"./locales/en/docs/divider.json":{title:`Divider`,description:`A thin line that separates content, horizontally or vertically, optionally with text.`,demos:{basic:{title:`Basic usage`,description:`A horizontal divider between two blocks of content.`},variants:{title:`Line styles`,description:`Solid (default), dashed or dotted.`},"with-text":{title:`With text`,description:`Children are rendered inside the line; textAlign places them left, center or right.`},vertical:{title:`Vertical`,description:`Use orientation="vertical" with a length to separate inline items.`},"custom-style":{title:`Custom style`,description:`Customize color, thickness, length, spacing and add a shadow with elevation.`}},api:{DividerProps:{variant:`Line style`,orientation:`Divider direction`,color:`Line color`,thickness:`Line thickness in pixels`,length:`Length of the line (width when horizontal, height when vertical)`,spacing:`Margin around the divider in pixels (top/bottom when horizontal, left/right when vertical)`,children:`Optional text rendered inside a horizontal divider`,textAlign:`Position of the text`,elevation:`Adds a subtle shadow`,className:`Additional class name`,style:`Inline styles`}}},"./locales/en/docs/dropdown.json":{title:`Dropdown`,description:`Shows a menu of actions or options when its trigger is clicked.`,demos:{basic:{title:`Basic usage`,description:`Without children a small default trigger button is rendered. onSelect receives the chosen item.`},"custom-trigger":{title:`Custom trigger`,description:`Any element can be the trigger: a Button, an IconButton or plain text, which becomes keyboard focusable.`},directions:{title:`Directions`,description:`Open the menu below (default), above, to the left or to the right of the trigger.`},disabled:{title:`Disabled`,description:`Disable individual items, or the whole dropdown.`},"custom-menu":{title:`Custom menu style`,description:`Customize the menu background, text color and shadow.`}},api:{DropdownProps:{className:`Additional class name`,ariaLabel:`Accessible label of the menu`,disabled:`Disables the dropdown`,items:`Menu items`,onSelect:`Called with the selected item; the menu closes afterwards`,menuBgColor:`Menu background color`,menuTextColor:`Menu text color`,menuBoxShadow:`Menu box shadow`,direction:`Side on which the menu opens`,children:`Trigger element; a small "Dropdown" button is rendered when omitted`},DropdownOption:{label:`Text of the menu item`,value:`Value of the menu item`,disabled:`Disables the menu item`}},a11y:{title:`Accessibility`,body:`The trigger gets aria-haspopup and aria-expanded. Enter, Space or ArrowDown opens the menu and focuses the first enabled item; ArrowUp/ArrowDown, Home and End move between items, Enter or Space selects, and Escape closes the menu and returns focus to the trigger. Set ariaLabel to name the menu.`}},"./locales/en/docs/empty.json":{title:`Empty`,description:`Placeholder shown when there is no data to display.`,demos:{basic:{title:`Basic usage`,description:`The default icon with the "No Data" description.`},svg:{title:`SVG illustration`,description:`useSvg switches to the built-in illustration.`},"custom-icon":{title:`Custom icon and description`,description:`Both icon and description accept any React node.`},"with-action":{title:`With action`,description:`Children are rendered in the footer, e.g. a call-to-action button.`},styled:{title:`Custom appearance`,description:`Size, background, text color and shadow can be customized.`}},api:{EmptyProps:{icon:`Custom icon, replacing the default one`,description:`Description text`,className:`Additional class name`,style:`Inline styles`,children:`Footer content, e.g. an action button`,useSvg:`Uses the built-in SVG illustration instead of the default icon`,width:`Width of the container`,height:`Height of the container`,backgroundColor:`Background color`,showShadow:`Adds a drop shadow`,color:`Text color`}}},"./locales/en/docs/hooks.json":{title:`Hooks`,description:`Low-level hooks behind ConfigProvider: manage the theme, the language and lib-core's translations yourself.`,reference:{title:`Reference`,text:`All hooks are exported from @minerva/lib-core.`,hook:`Hook`,signature:`Signature`,useAutoTheme:`Keeps the active theme in state and writes it as CSS variables on <html>. With "auto" or a { light, dark } pair it subscribes to prefers-color-scheme and unsubscribes on unmount. Returns the configured theme, its setter and the current system scheme.`,useLocale:`Keeps the locale in state and switches the language of lib-core's built-in texts (en, zh or fr). Returns the locale and its setter.`,useI18n:`Returns t and the i18next instance used by lib-core. It is a private instance, so your application's own i18next setup is never affected.`,global:`useAutoTheme and useLocale change global state (CSS variables on <html>, lib-core's language). The demos below start from the site's current settings and restore them when they unmount.`},standalone:{title:`Using the hooks without ConfigProvider`,text:`ConfigProvider is a thin wrapper around useAutoTheme and useLocale. If you don't need useConfig(), you can call the hooks directly, instead of a provider rather than inside one.`},demos:{"use-auto-theme":{title:`useAutoTheme`,description:`Switch the theme of the page with setTheme. systemTheme always reports the operating system scheme. Reset (or leaving the page) restores the site's theme.`},"use-locale":{title:`useLocale and useI18n`,description:`setLocale changes lib-core's language; t() from useI18n returns lib-core's built-in texts in that language.`}}},"./locales/en/docs/icon-button.json":{title:`IconButton`,description:`A compact button that only shows an icon, plus InteractiveIconButton presets that toggle between two states (favorite, like, bookmark...).`,demos:{basic:{title:`Basic usage`,description:`Pass any icon element. The button only contains an icon, so always give it an ariaLabel.`},variants:{title:`Variants`,description:`Without variant the button uses a neutral style; variant applies a semantic color.`},"sizes-and-shapes":{title:`Sizes and shapes`,description:`Three sizes (small, medium, large) and two shapes (circle, square).`},states:{title:`States`,description:`Loading replaces the icon with a spinner, active marks a pressed toggle and disabled removes the button from the tab order.`},"custom-colors":{title:`Custom colors`,description:`Override the icon color, background, hover background and active color.`},tooltip:{title:`Tooltip`,description:`Set showTooltip and tooltip to describe the action on hover and keyboard focus.`},interactive:{title:`InteractiveIconButton`,description:`A self-managed toggle: set the initial state with initialState and listen to changes with onChange.`},"interactive-types":{title:`Interactive presets`,description:`Every InteractiveIconType, i.e. every key of interactiveIconsMap. Each preset defines its icon, colors and tooltips. Click to toggle.`}},api:{IconButtonProps:{icon:`Icon element to display`,variant:`Color variant; a neutral style is used when omitted`,size:`Button size`,shape:`Button shape`,disabled:`Disables the button and removes it from the tab order`,loading:`Replaces the icon with a spinner and blocks interaction`,active:`Renders the button in its active (pressed) state`,className:`Additional class name`,color:`Custom icon color`,activeColor:`Custom icon color in the active state`,bgColor:`Custom background color`,hoverColor:`Custom background color on hover`,fillColor:`Custom fill color of the icon`,tooltip:`Tooltip configuration (content, variant, shape, arrow); requires showTooltip`,showTooltip:`Shows the tooltip on hover and focus`,ariaLabel:`Accessible label; always set it, since the button only contains an icon`},InteractiveIconProps:{type:`Preset that defines the icon, colors and tooltips (a key of interactiveIconsMap)`,onChange:`Called with the new state after each toggle`,initialState:`Initial active state (the component manages its state internally)`,className:`Additional class name`,size:`Button size`,shape:`Button shape`,disabled:`Disables the button`}}},"./locales/en/docs/installation.json":{title:`Installation`,description:`Add Minerva to a React project, load the stylesheet, and optionally register the Web Components.`,requirements:{title:`Requirements`,react:`React and React DOM 18 or later (peer dependencies of @minerva/lib-core).`,bundler:`A bundler that understands ES modules and CSS imports, such as Vite, webpack, Rspack or Next.js. A CommonJS build is shipped as well.`,browsers:`A modern evergreen browser: the theme tokens rely on CSS custom properties and color-mix().`},core:{title:`Install the React components`,text:`Install @minerva/lib-core with your package manager. Add react and react-dom if your project does not have them yet.`,peers:`react and react-dom are peer dependencies (>= 18) so your app keeps a single copy of React. i18next, react-i18next, react-icons and classnames are installed automatically as regular dependencies.`},styles:{title:`Import the stylesheet`,text:`The component styles and the default theme tokens are bundled in a single CSS file. Import it once, in your application's entry file:`,note:`Without @minerva/lib-core/style.css the components render unstyled. Import it only once; importing it from several modules is harmless but unnecessary.`},app:{title:`Your first component`,text:`Wrap the application in ConfigProvider and start using components:`,provider:`ConfigProvider is optional for rendering components, but it applies the theme (following the system color scheme by default), sets the language of lib-core's built-in texts and makes useConfig() available. Use one provider at the root of your app.`},webComponents:{title:`Web Components (optional)`,text:`@minerva/lib-web-components provides the same design as framework-agnostic custom elements. Install it and import the package once to register the elements:`,typings:`To get type checking and autocompletion for <minerva-button> in React JSX, reference the bundled typings once, for example in a global.d.ts file:`},typescript:{title:`TypeScript`,text:`Both packages ship their own type declarations; no @types package is needed. Props types (ButtonProps, TagProps, ...) and theme types (Theme, ComponentTheme, ThemeName, ...) are exported from the package root:`},next:{title:`Next steps`,introduction:`Design principles and the conventions used by every component.`,theming:`Built-in themes, design tokens and custom themes.`,components:`Start with the first component page and its live examples.`}},"./locales/en/docs/introduction.json":{title:`Introduction`,description:`The ideas behind Minerva, how to read the component pages, and the conventions shared by every component.`,principles:{title:`Design principles`,tokens:{title:`Token-driven`,text:`colors, radii and shadows come from CSS custom properties, so every component follows the active theme, including your own.`},accessible:{title:`Accessible by default`,text:`components render native, semantic elements, support the keyboard, show a visible focus ring and expose ariaLabel where a visible label may be missing.`},predictable:{title:`Predictable APIs`,text:`the same prop names (variant, size, shape, disabled, loading...) mean the same thing across components.`},small:{title:`Small and composable`,text:`components do one thing and accept className and style, so they are easy to combine with your own layout and styles.`}},reading:{title:`How to read the component pages`,text:`Every component page follows the same structure:`,import:`the exact import statement, including the stylesheet.`,examples:`live demos covering each feature. Use "Show code" to see the complete source; every demo is self-contained and can be copied as is.`,api:`tables generated from the component's TypeScript types, with the type, the default value and a description of every prop.`},conventions:{title:`Conventions`,controlled:{title:`Controlled and uncontrolled`,text:`Form components can manage their own state (pass defaultChecked / defaultValue, or nothing) or be controlled (pass checked / value together with onChange). Do not switch between the two modes during a component's lifetime.`},passthrough:{title:`className and style`,text:`Components accept className (and usually style) on their root element. Components that wrap a native element, such as Button, also forward the native attributes (type, name, data-*, aria-*...).`},aria:{title:`Accessible names`,text:`When a control has no visible text (an icon button, a search button, a close icon...), give it an accessible name with the ariaLabel prop. It is rendered as aria-label on the interactive element.`}},browsers:{title:`Browser support`,text:`Minerva targets current evergreen browsers: Chrome and Edge 111+, Firefox 113+ and Safari 16.2+. The theme relies on CSS custom properties and color-mix(); Internet Explorer is not supported. Server-side rendering works, the theme is applied on the client once React mounts.`},contributing:{title:`Contributing`,text:`Minerva is open source under the MIT license. Bug reports, ideas and pull requests are welcome on GitHub:`}},"./locales/en/docs/message.json":{title:`Message`,description:`Lightweight global feedback shown at the edge of the screen, called imperatively from anywhere.`,demos:{types:{title:`Types`,description:`message.success / error / info / warning / loading accept a string or any React node.`},options:{title:`Options`,description:`Pass an options object to set the duration, close button, icon, progress bar, hover behavior and more.`},placements:{title:`Placements`,description:`Six screen positions; messages at the same position are stacked.`},update:{title:`Update a message`,description:`Keep the returned id and call message.update to change the content, type or duration.`},"use-message":{title:`useMessage`,description:`The hook returns promise-based methods that resolve when the message closes, so steps can be chained with await.`},destroy:{title:`Close programmatically`,description:`message.destroy(id) closes one message; message.destroy() closes all of them.`}},api:{MessageProps:{id:`Unique id; generated automatically when omitted in MessageOptions`,type:`Message type, which sets the color. Set by the method you call (message.success, ...)`,content:`Message content`,duration:`Time in milliseconds before the message closes automatically; 0 keeps it open`,showClose:`Shows a close button`,icon:`Icon displayed before the content`,className:`Additional class name`,style:`Inline styles`,onClose:`Called with the message id when the message closes, whatever the reason`,showProgress:`Shows a countdown progress bar (only when duration > 0)`,pauseOnHover:`Pauses the countdown and progress bar while hovered`,placement:`Screen position of the message stack`,onClick:`Called when the message is clicked`,description:`Extra description exposed to assistive technologies (aria-description)`,closeAriaLabel:`Accessible label of the close button`,onUpdate:`Called after message.update() re-renders the message`,maxWidth:`Maximum width of the message`,zIndex:`z-index of the message`}},imperative:{title:`Imperative API`,intro:`Messages are not rendered as JSX. Call the global message object, or the useMessage hook inside components, and pass either the content or a MessageOptions object (MessageProps with an optional id).`,types:`Types`,columns:{method:`Method`,signature:`Signature`,returns:`Returns`,description:`Description`,type:`Type`,definition:`Definition`},rows:{show:`Shows a message of the given type and returns its id. A plain string or React element is used as content; an object with a content key is treated as options.`,update:`Merges new props into an open message and re-renders it, e.g. turning a loading message into a success. Unknown ids are ignored.`,destroy:`Closes the message with the given id, or every open message when called without an id. onClose is called for each closed message.`,hook:`Returns a stable object of promise-based methods for use inside components.`,hookShow:`Shows a message and returns a promise that resolves when it closes. The promise also exposes the message id as messageId.`,hookManage:`The same functions as message.update and message.destroy.`,options:`Options accepted by every show method: all MessageProps except that id is optional.`,promise:`Return value of the useMessage show methods.`},notes:{title:`Notes`,id:`Pass your own id to update or close a message later; otherwise use the returned id (message-0, message-1, …).`,onClose:`onClose is called exactly once per message, whether it closes on timeout, through the close button or through destroy.`,stacking:`Each placement has its own stack container appended to document.body; it is removed when its last message closes.`,promise:`To chain messages, await the promise or return only messageId from then(): returning the result itself would also wait for the next message to close.`}}},"./locales/en/docs/overview.json":{title:`Overview`,description:`Minerva is a UI library for the web: React components plus framework-agnostic Web Components, themable through CSS variables.`,what:{title:`What is Minerva`,p1:`Minerva helps you build consistent, accessible interfaces quickly. It ships a React component library and a small set of Lit-based custom elements that are developed together in one monorepo and share the same design language.`,p2:`Every component reads its colors, radii and shadows from CSS custom properties, so switching between light, dark or your own brand theme is a pure CSS-variable swap without re-rendering.`},packages:{title:`Packages`,core:`React (18+) components, ConfigProvider, theme utilities and hooks. ESM + CommonJS with TypeScript types.`,webComponents:`Framework-agnostic custom elements built with Lit, starting with <minerva-button>. Works in plain HTML, React, Vue and others.`},highlights:{title:`Highlights`,theming:{title:`Themes`,text:`light, dark and github-dark built in, "auto" mode that follows the operating system, and custom themes via ConfigProvider.`},i18n:{title:`Internationalization`,text:`lib-core ships its own translations for English, Chinese and French, isolated from your app's i18next instance.`},a11y:{title:`Accessibility`,text:`semantic elements, keyboard support, visible focus rings and ariaLabel props for icon-only controls.`},typescript:{title:`TypeScript`,text:`written in TypeScript; every component exports its props type, and themes are typed token maps.`},modules:{title:`Tree-shakable builds`,text:`ESM and CommonJS output with side-effect-free modules, plus one stylesheet to import.`}},quickLook:{title:`A quick look`,text:`Import the stylesheet once, wrap your app in ConfigProvider and use the components:`},explore:{title:`Explore the documentation`,text:`Every page has live examples with their source code and an API table generated from the component types.`}},"./locales/en/docs/pagination.json":{title:`Pagination`,description:`Splits long lists of data into pages and lets users move between them.`,demos:{basic:{title:`Basic usage`,description:`Pagination is controlled: keep the current page in state and update it in onChange.`},"many-pages":{title:`Many pages`,description:`With many pages, the first and last pages stay visible and ellipsis items jump 5 pages at a time.`},"total-and-jumper":{title:`Total and quick jumper`,description:`showTotal displays the number of items (customizable with totalRender); showQuickJumper adds a "Go to" input.`},"size-changer":{title:`Page size changer`,description:`showSizeChanger adds a page size selector; onChange then receives page 1 and the new page size.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},"shapes-and-variants":{title:`Shapes and variants`,description:`Combine a shape (rounded, circle, square) with a variant (filled, outlined, text).`},simple:{title:`Simple mode`,description:`Previous/next buttons with an editable page number.`},"custom-render":{title:`Custom rendering`,description:`Replace the icons, or render every item yourself with itemRender.`},disabled:{title:`Disabled`,description:`Disable all interaction.`},responsive:{title:`Responsive`,description:`responsive adapts the layout on small screens.`}},api:{PaginationProps:{current:`Current page (1-based); update it in onChange`,total:`Total number of items`,pageSize:`Number of items per page`,onChange:`Called with the new page and page size when the page or page size changes`,disabled:`Disables the pagination`,showQuickJumper:`Shows an input to jump to a page`,showSizeChanger:`Shows a page size selector`,pageSizeOptions:`Options of the page size selector`,itemRender:`Custom rendering of the page, prev/next and jump items`,className:`Additional class name`,style:`Inline styles`,showTotal:`Shows the total number of items`,totalRender:`Custom rendering of the total; range is the [first, last] item index of the current page`,size:`Pagination size`,shape:`Shape of the page items`,variant:`Visual style of the page items`,simple:`Simple mode: prev/next buttons with a page input`,responsive:`Adapts the layout to small screens`,icons:`Custom icons for the prev, next and jump items`}},a11y:{title:`Keyboard support`,body:`The pagination is a navigation landmark. When it has focus, ArrowLeft/ArrowRight go to the previous/next page and Home/End to the first/last page. Every item is focusable and can be activated with Enter or Space; the current page is marked with aria-current="page".`}},"./locales/en/docs/popper.json":{title:`Popper`,description:`Low-level positioned layer anchored to an element, used to build menus, dropdowns and popovers.`,demos:{basic:{title:`Basic usage`,description:`Popper is controlled: pass anchorEl and visible, update visibility in onVisibleChange and close with onClickAway.`},placements:{title:`Placements`,description:`Twelve placements around the anchor. With trigger="manual" you decide when it opens.`},triggers:{title:`Triggers`,description:`Click, hover, focus or right-click on the anchor requests a visibility change.`},variants:{title:`Variants and arrow`,description:`Color variants with an arrow pointing at the anchor.`},menu:{title:`Menu`,description:`type="menu" gives the popper role="menu" for lists of actions.`},sizes:{title:`Sizes and scrolling`,description:`Preset sizes with fixed dimensions; long content wraps with multiline and scrolls with scrollable.`},"custom-style":{title:`Custom style`,description:`Customize colors, dimensions, offset, transition and z-index.`}},api:{PopperProps:{anchorEl:`Element the popper is positioned against`,visible:`Whether the popper is visible (controlled)`,children:`Popper content`,placement:`Placement relative to the anchor`,variant:`Color variant`,type:`Functional type; "menu" sets role="menu", otherwise role="dialog"`,offset:`Position offset in pixels`,animation:`Transition settings`,arrow:`Shows an arrow pointing at the anchor`,zIndex:`z-index of the popper`,onClickAway:`Called on mousedown outside both the popper and the anchor`,className:`Additional class name`,tabIndex:`tabIndex of the popper element`,ariaLabel:`Accessible label of the popper`,popperStyle:`Custom colors and dimensions`,size:`Preset size; "auto" fits the content`,multiline:`Allows text to wrap onto multiple lines`,trigger:`Anchor interaction that requests a visibility change via onVisibleChange`,onVisibleChange:`Called with the requested visibility when the trigger fires`,scrollable:`Lets the content scroll when it overflows`,width:`Fixed width, overriding the size preset`,height:`Fixed height, overriding the size preset`},PopperOffset:{x:`Horizontal offset in pixels`,y:`Vertical offset in pixels`},PopperAnimation:{duration:`Duration in milliseconds`,easing:`CSS timing function`},PopperCustomStyle:{backgroundColor:`Background color`,color:`Text color`,width:`Width`,height:`Height`,maxWidth:`Max width`,maxHeight:`Max height`,minWidth:`Min width`,minHeight:`Min height`,padding:`Padding`,borderColor:`Border color`}}},"./locales/en/docs/progress.json":{title:`ProgressIndicator`,description:`An indeterminate loading indicator for operations of unknown duration.`,demos:{types:{title:`Types`,description:`Spinner (default), circle, wave, bar and dotted bar.`},sizes:{title:`Sizes`,description:`Small, medium (default) and large.`},width:{title:`Width`,description:`Set a fixed width, or use full to fill the container.`},"with-icon":{title:`With icon`,description:`Show an icon before the indicator. Always describe what is loading with ariaLabel.`}},api:{ProgressIndicatorProps:{type:`Indicator style`,size:`Indicator size`,icon:`Icon displayed before the indicator`,ariaLabel:`Accessible label describing what is loading`,className:`Additional class name`,width:`Custom width (ignored when full is set)`,full:`Stretches the indicator to the full width of its container`}}},"./locales/en/docs/radio.json":{title:`Radio`,description:`Lets users pick exactly one option from a set. Use RadioGroup to manage the selection of several radios.`,demos:{basic:{title:`Basic usage`,description:`An uncontrolled RadioGroup with a defaultValue. Each Radio is identified by its value.`},controlled:{title:`Controlled`,description:`Pass value and onChange to RadioGroup to keep the selection in your own state.`},horizontal:{title:`Horizontal layout`,description:`Radios are stacked vertically by default; set direction="horizontal" to lay them out in a row.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large. A group size applies to all of its radios.`},colors:{title:`Colors`,description:`Use type for preset color schemes, or color (on a Radio or a RadioGroup) for any CSS color.`},disabled:{title:`Disabled`,description:`Disable a single option, or the whole group at once.`},validation:{title:`Validation and helper text`,description:`RadioGroup supports required, error and helperText. A standalone Radio can show errorMessage (with errorIcon) or helperText.`}},api:{RadioProps:{checked:`Whether the radio is checked (controlled). Ignored inside a RadioGroup`,defaultChecked:`Initial checked state (uncontrolled). Ignored inside a RadioGroup`,disabled:`Disables the radio`,name:`Native name attribute. Inside a RadioGroup the group's name is used`,value:`Value of the radio; identifies it within a RadioGroup`,onChange:`Called when the checked state changes (standalone radios only; inside a group use RadioGroup's onChange)`,size:`Radio size. Overridden by the RadioGroup size`,type:`Color scheme of the radio`,label:`Text label displayed next to the radio`,className:`Additional class name`,color:`Custom color of the radio mark. Overridden by the RadioGroup color`,bgColor:`Custom background color of the radio mark`,required:`Marks the input as required`,error:`Shows the error state (errorMessage replaces helperText)`,errorIcon:`Icon shown before the error message`,errorMessage:`Message shown below the radio when error is true`,helperText:`Helper text shown below the radio`,ref:`Ref forwarded to the native input element`},RadioGroupProps:{value:`Value of the selected radio (controlled)`,defaultValue:`Initially selected value (uncontrolled)`,name:`Name shared by all radios of the group`,onChange:`Called with the newly selected value`,disabled:`Disables every radio in the group`,children:`Radio elements`,className:`Additional class name`,direction:`Layout direction of the radios`,size:`Size applied to every radio in the group`,error:`Shows the error state`,helperText:`Helper text shown below the group`,required:`Marks the group as required (aria-required)`,color:`Color applied to every radio in the group`}}},"./locales/en/docs/search-button.json":{title:`SearchButton`,description:`A button with a built-in search icon, with optional text, animations and a loading state.`,demos:{basic:{title:`Basic usage`,description:`An icon-only search button. Give it an ariaLabel so screen readers can announce it.`},variants:{title:`Variants`,description:`Five color variants: primary (default), success, warning, error and info.`},sizes:{title:`Sizes`,description:`Four sizes: small, medium (default), large and xlarge.`},shapes:{title:`Shapes`,description:`Circle (default), rounded or square.`},animations:{title:`Animations`,description:`Hover animations: expand, shrink or shake.`},"with-text":{title:`With text`,description:`Children are rendered next to the icon; a button with text is always rendered square.`},states:{title:`States`,description:`Loading shows a spinner instead of the icon; disabled blocks clicks.`},"custom-colors":{title:`Custom colors`,description:`Override the background, icon and text colors.`}},api:{SearchButtonProps:{onClick:`Called when the button is clicked (not called while disabled)`,className:`Additional class name`,ariaLabel:`Accessible label; required when the button has no text`,disabled:`Disables the button`,shape:`Button shape; buttons with children are always rendered square`,variant:`Color variant`,animation:`Hover animation`,size:`Button size`,color:`Text color`,iconColor:`Color of the search icon`,bgColor:`Custom background color`,loading:`Replaces the icon with a loading spinner`,children:`Optional text shown next to the icon`}}},"./locales/en/docs/skeleton.json":{title:`Skeleton`,description:`Placeholder shapes shown while content is loading.`,demos:{basic:{title:`Basic usage`,description:`Text lines; set how many with lines.`},variants:{title:`Variants`,description:`Text, circular, rectangular, rounded, button and image shapes.`},animations:{title:`Animations`,description:`Pulse (default), wave, or "false" for no animation.`},composition:{title:`Avatar, title and paragraph`,description:`Combine an avatar with a title and paragraph, or with plain lines.`},card:{title:`Card`,description:`The card variant lays out an avatar, title and paragraph; active highlights it.`},loading:{title:`Loading state`,description:`Wrap the real content and render it once loading is false.`}},api:{SkeletonProps:{variant:`Shape of the placeholder`,animation:`Loading animation; "false" disables it`,width:`Width of each line (numbers are pixels)`,height:`Height of each line (numbers are pixels)`,className:`Additional class name`,children:`Real content, rendered once loading is false`,loading:`Shows the placeholder; set to false to render children`,borderRadius:`Custom corner radius of each line`,style:`Inline styles applied to each line`,lines:`Number of lines to render`,avatar:`Shows an avatar placeholder`,avatarSize:`Avatar size (numbers are pixels)`,avatarShape:`Avatar shape`,active:`Highlights the card variant as active`,paragraph:`Shows a paragraph placeholder (replaces the lines)`,title:`Shows a title placeholder (replaces the lines)`}}},"./locales/en/docs/space.json":{title:`Space`,description:`Sets consistent spacing between inline or stacked elements.`,demos:{basic:{title:`Basic usage`,description:`Wrap elements in Space to separate them with a medium (16px) gap.`},sizes:{title:`Sizes`,description:`Preset sizes small (8px), medium (16px) and large (24px), or any number of pixels.`},vertical:{title:`Vertical`,description:`Stack items vertically with direction="vertical".`},alignment:{title:`Alignment`,description:`align positions items on the cross axis; justify distributes them on the main axis (use block to give it room).`},wrap:{title:`Wrap`,description:`Let items wrap onto multiple lines when the container is too narrow.`},split:{title:`Separator`,description:`Render a separator, such as a vertical Divider, between items.`},"compact-and-block":{title:`Compact and block`,description:`compact halves the preset gap; block stretches the container to the full width.`}},api:{SpaceProps:{align:`Alignment of the items on the cross axis`,justify:`Alignment of the items on the main axis`,direction:`Layout direction`,size:`Gap between items: a preset (small = 8px, medium = 16px, large = 24px) or a number of pixels`,wrap:`Wraps items onto multiple lines (horizontal only)`,split:`Separator rendered between items`,compact:`Compact mode: halves the preset gap`,block:`Stretches the container to the full width of its parent`,className:`Additional class name`,style:`Inline styles`,children:`Items to space out`}}},"./locales/en/docs/status-indicator.json":{title:`StatusIndicator`,description:`A small badge that shows the status of an item or the presence of a user.`,demos:{statuses:{title:`Statuses`,description:`Four semantic statuses, each with its own color and icon.`},shapes:{title:`Shapes`,description:`Circle (default), rounded or square.`},sizes:{title:`Sizes`,description:`Small, medium (default) and large.`},presence:{title:`Presence`,description:`Use type to show user presence: online, away, busy or offline.`},"custom-color":{title:`Custom color`,description:`Set type="custom" and pass any CSS color.`},disabled:{title:`Disabled`,description:`Clicking an indicator plays a short feedback animation; disabled turns it off.`}},api:{StatusIndicatorProps:{className:`Additional class name`,ariaLabel:`Accessible label describing the status`,disabled:`Disables the click feedback animation`,status:`Status, which sets the color and icon`,shape:`Shape of the indicator`,type:`Presence type; overrides the status color. Use "custom" together with color`,showLabel:`Shows a text label next to the indicator (presence types only)`,size:`Indicator size`,color:`Custom background color, applied when type is "custom"`}}},"./locales/en/docs/switch.json":{title:`Switch`,description:`Toggles a single setting on or off, with immediate effect.`,demos:{basic:{title:`Basic usage`,description:`Uncontrolled switches with a label; defaultChecked sets the initial state.`},controlled:{title:`Controlled`,description:`Use checked together with onChange to drive the switch from your state.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},colors:{title:`Colors`,description:`Use a theme color name or any CSS color for the checked state.`},"label-placement":{title:`Label placement`,description:`Place the label before ("start") or after ("end", default) the switch with labelPlacement.`},states:{title:`Loading and disabled`,description:`loading shows a busy state and, like disabled, blocks interaction.`},icons:{title:`Icons`,description:`Render a small icon inside the thumb with icon.`},"custom-style":{title:`Shape and custom styles`,description:`Square shape, no ripple, and custom trackStyle / thumbStyle.`}},api:{SwitchProps:{checked:`Whether the switch is on (controlled)`,defaultChecked:`Initial state (uncontrolled)`,disabled:`Disables the switch`,size:`Switch size`,color:`Color when on: a theme color name or any CSS color`,shape:`Shape of the track and thumb`,label:`Label displayed next to the switch`,labelPlacement:`Position of the label relative to the switch`,loading:`Shows a loading state and blocks interaction`,ripple:`Shows a ripple effect on click`,className:`Additional class name`,labelStyle:`Inline styles of the root label element`,trackStyle:`Inline styles of the track`,thumbStyle:`Inline styles of the thumb`,onChange:`Called when the state changes`,onFocus:`Called when the switch receives focus`,onBlur:`Called when the switch loses focus`,icon:`Custom icon`,iconPlacement:`Icon position: inside the thumb ("start") or after the switch ("end")`}}},"./locales/en/docs/tag.json":{title:`Tag`,description:`Small labels for marking and categorizing content; can be closable or clickable.`,demos:{basic:{title:`Basic usage`,description:`Use variant to convey meaning.`},"sizes-shapes":{title:`Sizes and shapes`,description:`Three sizes and three shapes: square, rounded (default) and circle.`},"with-icon":{title:`With icon`,description:`icon is displayed before the content.`},"bordered-elevation":{title:`Border and shadow`,description:`Add a border with bordered and a shadow with elevation.`},closable:{title:`Closable`,description:`closable adds a close button that calls onClose; remove the tag from your state there. closeIcon and closeLabel customize the button.`},clickable:{title:`Clickable (selectable)`,description:`clickable tags are buttons: focus them with Tab and activate them with a click, Enter or Space. Here they toggle a selection.`},"custom-colors":{title:`Custom colors`,description:`bgColor, textColor and borderColor override the variant colors; ripple={false} disables the click ripple.`},disabled:{title:`Disabled`,description:`Disabled tags ignore clicks, are removed from the tab order and disable their close button.`}},accessibility:{title:`Accessibility`,clickable:`With clickable, the tag gets role="button" and tabIndex=0, and Enter or Space trigger onClick just like a mouse click. Use it for actions or toggles, not for navigation (use a link instead).`,closable:`The close button is a native <button> with its own tab stop. Its accessible name defaults to "Close"; set closeLabel (e.g. "Remove React") so screen-reader users know which tag it removes.`,disabled:`A disabled clickable tag keeps role="button" with aria-disabled="true" and is skipped by Tab. When the selected state matters, also convey it in text or with aria attributes, not only with color.`},api:{TagProps:{children:`Content of the tag`,variant:`Color scheme`,size:`Tag size`,shape:`Tag shape`,closable:`Shows a close button`,onClose:`Called when the close button is clicked`,clickable:`Makes the tag behave like a button (focusable, activated with Enter / Space)`,onClick:`Called when the tag is activated (requires clickable)`,icon:`Icon displayed before the content`,bordered:`Shows a border`,elevation:`Shows a shadow`,bgColor:`Custom background color`,textColor:`Custom text color`,borderColor:`Custom border color`,className:`Additional class name`,style:`Inline styles`,disabled:`Disables the tag and its close button`,closeIcon:`Custom close icon`,closeLabel:`Accessible label of the close button`,ripple:`Shows a ripple effect on click`}}},"./locales/en/docs/textfield.json":{title:`TextField`,description:`A single-line text input with a floating label, icons, validation message and many styling options.`,demos:{basic:{title:`Basic usage`,description:`name and label are required. The label floats above the value; a placeholder replaces it.`},controlled:{title:`Controlled`,description:`Pass value and onChange to control the field. onChange receives the new string value.`},icons:{title:`Icons`,description:`Show an icon on the left (default) or on the right.`},password:{title:`Password`,description:`With type="password" and a right icon, the icon becomes a show/hide toggle.`},"clearable-and-count":{title:`Clearable and character count`,description:`clearable shows a clear button when the field has a value; showCharCount displays the length.`},appearance:{title:`Appearance`,description:`Minimal (bottom border only), borderless, or a custom border radius and color.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},"width-and-suffix":{title:`Width and suffix`,description:`Set a width or use fullWidth; suffix displays content such as a unit at the end.`},states:{title:`States`,description:`Disabled and read-only fields. Read-only fields hide the floating label, so give them an ariaLabel.`},validation:{title:`Validation`,description:`helperText shows an error message and switches the field to the error state. Submit an invalid email to see it.`}},api:{TextFieldProps:{name:`Name of the input; also used as its id to link the label`,label:`Floating label (hidden when a placeholder is set or the field is read-only)`,value:`Current value; omit for an uncontrolled field`,placeholder:`Placeholder text, replaces the floating label`,helperText:`Error message shown below the field; switches it to the error state`,icon:`Icon shown inside the field`,iconPosition:`Side of the icon; with type="password" a right icon becomes a show/hide toggle`,borderColor:`Custom border color`,hideBorder:`Hides the border`,minimal:`Minimal style with only a bottom border`,borderRadius:`Corner radius (any CSS length)`,type:`Native input type`,showCharCount:`Shows the number of characters`,clearable:`Shows a clear button when the field has a value`,fullWidth:`Takes the full width of the container (overrides width)`,width:`Width of the field (any CSS length)`,disabled:`Disables the field`,ariaLabel:`Accessible label of the input`,readOnly:`Makes the field read-only`,size:`Field size`,suffix:`Content shown at the end of the field, e.g. a unit`,onChange:`Called with the new value on every change; pass value as well to control the field`,onBlur:`Called when the input loses focus`,onFocus:`Called when the input gains focus`,onKeyDown:`Called on key down in the input`,className:`Additional class name of the container`}}},"./locales/en/docs/theme-utils.json":{title:`Theme utilities`,description:`Functions and theme objects to resolve, apply and inspect themes outside of ConfigProvider.`,reference:{title:`Reference`,text:`ConfigProvider and useAutoTheme are built on these helpers. Use them to apply a theme without React, to theme a single element, or to read token values.`,name:`Name`,signature:`Signature`,applyThemeStyles:`Resolves a theme and writes it as CSS variables on <html> (global). Variables of the previous theme that the new one doesn't define are removed.`,generateCSSVariables:`Writes every token of a theme object as --<token> on the given style declaration (e.g. element.style) and removes stale ones. Use it to theme one element.`,resolveTheme:`Turns any accepted theme value into a theme object: "auto" and { light, dark } pairs use systemTheme, names are looked up in themes, objects are returned as is. Throws for unknown names. Pure.`,getSystemTheme:`Returns the operating system color scheme from prefers-color-scheme; "light" when matchMedia is unavailable (SSR, tests).`,isBilingualTheme:`Type guard: true for { light, dark } pairs of theme objects.`,themes:`The built-in themes keyed by the names accepted by the theme prop.`,builtIns:`The built-in theme objects, also exported individually; spread them to create custom themes.`},usage:{apply:`Applying a theme globally`,applyText:`applyThemeStyles is what ConfigProvider calls. Use it in non-React code, or to apply the theme before the first render to avoid a flash of the default colors.`,generate:`Theming one element`,generateText:`generateCSSVariables accepts any CSSStyleDeclaration, so the tokens can be scoped to an element: its descendants inherit them.`,resolve:`Resolving themes`,resolveText:`resolveTheme, isBilingualTheme and getSystemTheme have no side effects; use them to compute token values, e.g. to style a canvas or a chart.`},demos:{"theme-swatches":{title:`Built-in themes`,description:`Reads token values from the themes map and renders them as swatches. No CSS variable is written.`},"resolve-theme":{title:`Resolving a theme value`,description:`How resolveTheme resolves each kind of theme value for a given system scheme, and what isBilingualTheme / getSystemTheme return.`},"scoped-preview":{title:`Previewing a theme in an element`,description:`generateCSSVariables writes a resolved theme on a container's style, so only the components inside it change.`}},api:{ThemeProps:{"primary-color":`Brand / accent color: primary buttons, active states, focus rings.`,"secondary-color":`Neutral accent used by secondary variants.`,"success-color":`Positive status color (success variants).`,"danger-color":`Destructive / error status color (danger and error variants).`,"warning-color":`Warning status color.`,"info-color":`Informational status color.`,"light-color":`A light neutral (legacy; light variants).`,"dark-color":`A dark neutral (legacy; dark variants).`,"background-color":`Page background. Default for --surface-color.`,"foreground-color":`Main text color. Default for --text-color.`,"border-color":`Default border / divider color.`,"text-gray":`Secondary, low-emphasis text (should keep at least 4.5:1 contrast on the background).`,"primary-gradient-start":`Start color of the primary gradient.`,"primary-gradient-end":`End color of the primary gradient.`,"secondary-gradient-start":`Start color of the secondary gradient.`,"secondary-gradient-end":`End color of the secondary gradient.`,"highlight-color":`Highlight / mark color.`,"shadow-color":`Base shadow color used by --shadow-sm, --shadow-md and --shadow-lg.`,"muted-color":`Muted UI color (placeholders, icons, inactive controls).`,"link-color":`Link color.`,"link-hover-color":`Link color on hover.`,"link-active-color":`Link color while pressed.`,"link-visited-color":`Color of visited links.`},SemanticThemeProps:{"surface-color":`Background of cards, inputs and other component surfaces.`,"surface-muted-color":`Hovered rows, disabled controls, tracks.`,"surface-elevated-color":`Popovers, menus, dropdowns, tooltips.`,"overlay-color":`Backdrop / modal overlay.`,"border-strong-color":`Higher-contrast border (inputs, hovered borders).`,"text-color":`Main text color (defaults to --foreground-color).`,"text-secondary-color":`Secondary text (descriptions, helper text).`,"text-disabled-color":`Disabled text.`,"text-inverse-color":`Text drawn on filled role backgrounds (e.g. a primary button).`,"focus-ring-color":`Focus outline / ring color.`,"error-color":`Alias of --danger-color.`,"shadow-sm":`Small elevation shadow.`,"shadow-md":`Medium elevation shadow (popovers, menus).`,"shadow-lg":`Large elevation shadow (dialogs, overlays).`,"radius-sm":`Small corner radius.`,"radius-md":`Medium corner radius.`,"radius-lg":`Large corner radius.`},ComponentThemeProps:{"btn-bg-color-success":`Overrides the background of success buttons.`,"btn-bg-color-danger":`Overrides the background of error / danger buttons.`,"btn-bg-color-warning":`Overrides the background of warning buttons.`,"btn-bg-color-info":`Overrides the background of info buttons.`,"btn-bg-color-hover":`Overrides the hover background of primary buttons.`,"btn-bg-color-active":`Overrides the active background of primary buttons.`,"avatar-bg-color-info":`Background of info avatars.`,"avatar-bg-color-success":`Background of success avatars.`,"avatar-bg-color-danger":`Background of danger avatars.`,"avatar-bg-color-warning":`Background of warning avatars.`,"card-bg-color":`Card background (defaults to --surface-color).`,"card-bg-color-content":`Card content background (defaults to --surface-color).`,"card-border-color":`Card border (defaults to --border-color).`}}},"./locales/en/docs/theming.json":{title:`Theming`,description:`Built-in light and dark themes, design tokens as CSS variables, and how to create your own theme.`,builtIn:{title:`Built-in themes`,text:`lib-core ships three themes: light, dark and github-dark. Pick one with the theme prop of ConfigProvider, or keep the default "auto", which follows the operating system's color scheme and updates live when it changes.`},live:{title:`Try it`,text:`This switcher drives the theme of the whole documentation site. The components below, and every page, update instantly because they only read CSS variables.`,current:`Applied theme:`,alert:`Components re-theme without re-rendering: only the CSS variables on <html> change.`},values:{title:`Accepted theme values`,text:`The theme prop of ConfigProvider (and useAutoTheme / applyThemeStyles) accepts:`,value:`Value`,auto:`Default. Uses light or dark according to prefers-color-scheme and follows changes.`,light:`The built-in light theme.`,dark:`The built-in dark theme.`,githubDark:`A dark theme based on GitHub's dark palette.`,object:`A complete theme object (every base token, plus optional semantic and component tokens). Usually built by spreading a built-in theme.`,pair:`Two theme objects; the one matching the system color scheme is applied and switches automatically.`},how:{title:`How it works`,p1:`A theme is a flat map of token names to CSS values. ConfigProvider writes every entry as a CSS custom property named --<token> in the inline style of the <html> element:`,p2:`Component styles only reference these variables (for example background: var(--primary-color)), so changing theme never re-renders React components. The stylesheet also declares every token on :root, so components are styled with the light values even before (or without) a ConfigProvider.`},demos:{"scoped-theme":{title:`Scoped theme`,description:`Tokens are ordinary CSS variables: override them on a wrapper element to re-theme only part of the page.`}},custom:{title:`Custom themes`,text:`Create a theme by spreading a built-in one and overriding the tokens you need, then pass it to ConfigProvider. Pass a { light, dark } pair to keep following the system color scheme. Semantic tokens such as hover, subtle background and focus ring colors are derived from the base tokens, so overriding primary-color is usually enough.`},css:{title:`Overriding tokens with CSS`,text:`You can also set tokens from a plain stylesheet. Keep in mind where each value is defined:`,note:`ConfigProvider writes the active theme as inline styles on <html>, which take precedence over :root rules in a stylesheet. Tokens set by the theme need !important to be overridden globally; component tokens (btn-*, card-*, avatar-*) are not set by the built-in themes and can be defined normally.`},tokens:{title:`Token reference`,text:`Every token is available as var(--<token>). Swatches show the value of the current theme.`,variable:`CSS variable`,base:`Base tokens`,baseText:`Required in every theme object (ThemeProps).`,semantic:`Semantic tokens`,semanticText:`Optional (SemanticThemeProps). Their defaults are derived from the base tokens with color-mix(); the built-in dark themes set some of them explicitly.`,roles:`Role tokens`,rolesText:`Each role color gets derived hover, active, subtle (tinted background), border and text tokens, e.g. --primary-color-hover or --danger-color-subtle.`,role:`Role`,component:`Component tokens`,componentText:`Optional per-component overrides (ComponentThemeProps). Components fall back to the semantic tokens when they are not set.`}},"./locales/en/docs/time-picker.json":{title:`TimePicker`,description:`Picks a time of day from hour, minute and second columns, or by typing it.`,demos:{basic:{title:`Basic usage`,description:`Click the input to open the panel. onChange receives a Date, or undefined when cleared.`},"default-value":{title:`Default value and clearing`,description:`defaultValue sets the initial time. Set clearable={false} to hide the clear button.`},formats:{title:`Formats`,description:`Supported formats are HH:mm:ss and HH:mm (plus their 12-hour variants). Hide the seconds column with showSecond={false}.`},"twelve-hour":{title:`12-hour clock`,description:`use12Hours adds an AM/PM column; combine it with the hh:mm:ss a or hh:mm a format.`},steps:{title:`Steps`,description:`hourStep, minuteStep and secondStep set the interval between options.`},"time-range":{title:`Time range`,description:`minTime and maxTime disable the options outside the allowed range.`},sizes:{title:`Sizes`,description:`Three sizes: small, medium (default) and large.`},disabled:{title:`Disabled`,description:`A disabled picker cannot be opened or edited.`}},api:{TimePickerProps:{value:`Selected time (only read on mount; the date part is ignored)`,defaultValue:`Initially selected time (uncontrolled)`,onChange:`Called with the new time, or undefined when the value is cleared`,format:`Display format: "HH:mm:ss", "HH:mm", "hh:mm:ss a" or "hh:mm a"`,use12Hours:`Uses a 12-hour clock with an AM/PM column`,placeholder:`Placeholder of the input`,disabled:`Disables the picker`,clearable:`Allows clearing the value with the suffix button`,size:`Size of the input and panel`,className:`Additional class name`,minTime:`Earliest selectable time; earlier options are disabled`,maxTime:`Latest selectable time; later options are disabled`,showSecond:`Shows the seconds column`,hourStep:`Interval between hour options`,minuteStep:`Interval between minute options`,secondStep:`Interval between second options`}}},"./locales/en/docs/tooltip.json":{title:`Tooltip`,description:`A short text label shown when the user hovers over or focuses an element.`,demos:{basic:{title:`Basic usage`,description:`Wrap a focusable element. The tooltip shows on hover and on keyboard focus, and Escape closes it.`},placements:{title:`Placements`,description:`Twelve placements around the trigger.`},variants:{title:`Variants`,description:`Dark (default), light and semantic color variants.`},shapes:{title:`Shapes`,description:`Default, rounded, square and thought-bubble shapes.`},animations:{title:`Animations`,description:`Choose how the tooltip enters and leaves.`},"custom-colors":{title:`Colors, arrow and offset`,description:`bgColor accepts solid colors and CSS gradients; arrow adds a pointer; offset moves the tooltip away from the trigger.`},delays:{title:`Delays and disabled`,description:`enterDelay and leaveDelay control the hover timing; disabled turns the tooltip off.`},"follow-cursor":{title:`Follow cursor`,description:`With followCursor the tooltip tracks the mouse pointer.`},controlled:{title:`Controlled and imperative`,description:`Control visibility with open, or call open / close / toggle on a TooltipRef.`},events:{title:`Events`,description:`onOpen and onClose fire on hover, focus, blur and Escape.`}},api:{TooltipProps:{content:`Content displayed inside the tooltip`,children:`The element that triggers the tooltip; prefer a focusable element`,open:`Whether the tooltip is shown (controlled)`,defaultOpen:`Initial open state (uncontrolled)`,placement:`Placement relative to the trigger`,variant:`Color variant`,shape:`Shape of the tooltip`,animation:`Show / hide animation`,enterDelay:`Delay before showing on hover, in milliseconds`,leaveDelay:`Delay before hiding on mouse leave, in milliseconds`,offset:`Offset from the trigger as [x, y] in pixels`,followCursor:`Makes the tooltip follow the mouse cursor`,bgColor:`Custom background color (CSS gradients are supported)`,textColor:`Custom text color`,zIndex:`z-index of the tooltip`,arrow:`Shows an arrow pointing at the trigger`,disabled:`Disables the tooltip`,className:`Additional class name of the trigger wrapper`,onOpen:`Called when the tooltip opens from hover or focus`,onClose:`Called when the tooltip closes from mouse leave, blur or Escape`,ariaLabel:`Accessible label of the tooltip element`},TooltipRef:{open:`Opens the tooltip`,close:`Closes the tooltip`,toggle:`Toggles the tooltip`}}},"./locales/en/docs/virtual-list.json":{title:`VirtualList`,description:`Renders long lists efficiently by only mounting the rows that are visible in the scroll container.`,demos:{basic:{title:`Basic usage`,description:`10,000 rows with a fixed itemHeight; only the visible rows (plus overscan) are in the DOM.`},"auto-height":{title:`Measured row height`,description:`Omit itemHeight to measure it from the first rendered item; itemPadding is added around each row.`},"infinite-scroll":{title:`Infinite scroll`,description:`onLoadMore is called near the bottom of the list; show a loading indicator while it resolves.`},"high-performance":{title:`High performance mode`,description:`highPerformance batches scroll updates with requestAnimationFrame and requestIdleCallback, here with 100,000 rows.`}},api:{VirtualListProps:{items:`Items to render`,itemHeight:`Fixed row height in pixels; measured from the first item when omitted`,itemPadding:`Padding of each row in pixels`,overscan:`Number of rows rendered above and below the visible area`,maxHeight:`Maximum height of the scroll container in pixels`,renderItem:`Renders the content of one row`,className:`Additional class name`,style:`Inline styles of the scroll container`,onLoadMore:`Called when scrolling near the bottom; return a promise that resolves once new items are loaded`,loadMoreThreshold:`Distance from the bottom (px) at which onLoadMore is triggered`,highPerformance:`Batches scroll updates with requestAnimationFrame and requestIdleCallback`,loading:`Shows a loading indicator at the bottom of the list`},VirtualListItem:{id:`Unique key of the item`,metadata:`Arbitrary data for renderItem`}}},"./locales/en/docs/web-components.json":{title:`Web Components`,description:`<minerva-button>: a framework-agnostic custom element built with Lit, usable in plain HTML, React, Vue or any other framework.`,what:{title:`What it is`,p1:`@minerva/lib-web-components packages Minerva components as standard custom elements. Importing the package once registers them with the browser; after that they behave like built-in HTML tags in any page or framework.`,p2:`The elements render into a shadow root, so their internal styles cannot leak into your page (or be broken by it). They are configured with HTML attributes and emit regular DOM events such as click.`},html:{title:`Usage in HTML`,text:`Load the package as an ES module (through your bundler), then use the tags anywhere in the document. Boolean attributes such as loading or disabled are on when present.`},react:{title:`Usage in React`,text:`Import the package once for its side effect, and reference the bundled typings to type-check attributes in JSX. onClick and other DOM events work as usual; use aria-label (with a dash) for the accessible name.`,booleans:`React 18 sets attributes on custom elements as strings, so loading={false} becomes loading="false", which still counts as present. Pass true or undefined (e.g. loading={saving || undefined}) to toggle boolean attributes. React 19 sets them as properties and accepts plain booleans.`},other:{title:`Vue and other frameworks`,text:`Any framework that renders HTML can use the elements. In Vue, declare minerva-* tags as custom elements so the compiler doesn't try to resolve them as Vue components, and bind null to remove a boolean attribute. Angular needs CUSTOM_ELEMENTS_SCHEMA; Svelte, Solid and Lit work without configuration.`},theming:{title:`Theming`,text:`The button reads its own CSS custom properties (--primary-color, --primary-hover, --error-color, ...) with defaults declared on the element, so it does not automatically follow lib-core's ConfigProvider theme. Set the variables on the element, or in a rule that targets it, to match your design:`},a11y:{title:`Accessibility`,text:`The element renders a native <button> inside its shadow root, so it is focusable and keyboard-operable. The aria-label attribute is forwarded to that button; set it on icon-only buttons. While loading, the button sets aria-busy and ignores clicks; disabled buttons are not focusable.`},demos:{basic:{title:`Basic usage`,description:`Import the package once, then use <minerva-button> like any element. React's onClick works as with native elements.`},variants:{title:`Variants`,description:`Nine variants: primary, secondary, success, warning, error, info, ghost, retry and back.`},"sizes-shapes":{title:`Sizes and shapes`,description:`Four sizes (tiny to large) and four shapes. Icon-only circle buttons need an aria-label.`},states:{title:`States`,description:`loading shows a spinner and blocks clicks; disabled and active are boolean attributes too. In React 18 pass true or undefined, never false.`}},api:{wc_ButtonProps:{variant:`Visual style of the button (reflected to the variant attribute).`,size:`Button size.`,shape:`Corner shape of the button.`,disabled:`Disables the button (boolean attribute).`,loading:`Shows a spinner instead of the content and blocks clicks; sets aria-busy.`,active:`Renders the button in its pressed / active style.`,ariaLabel:`Accessible label forwarded to the inner <button>; set it with the aria-label attribute. Required for icon-only buttons.`}}}});export{e as default};